// Writes what the config generator renders for each scenario into
// crates/config/tests/fixtures/config-generator/<name>.toml, where
// `cargo test -p batlehub-config --test config_generator_fixtures` loads it
// with the real parser and validator: the check the node harness cannot
// make. `--check` regenerates to memory and fails on any drift, like the
// endpoint tables (task docs:generator:check).
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { renderConfigToml } from "../.vitepress/components/configToml.ts";
import { scenarios } from "./config-generator-scenarios.ts";

const here = dirname(fileURLToPath(import.meta.url));
const DIR = join(here, "..", "..", "crates", "config", "tests", "fixtures", "config-generator");
const HEADER =
  "# Generated by docs/build/config-generator-fixtures.ts from the docs site's config\n" +
  "# generator (docs/.vitepress/components/configToml.ts) — do not edit; run\n" +
  "# `task docs:generator` and commit the result.\n\n";

const wanted = new Map(scenarios().map((s) => [`${s.name}.toml`, HEADER + renderConfigToml(s.state) + "\n"]));

if (process.argv.includes("--check")) {
  const present = new Set(readdirSync(DIR).filter((f) => f.endsWith(".toml")));
  const stale: string[] = [];
  for (const [name, body] of wanted) {
    if (!present.has(name)) stale.push(`${name} (missing)`);
    else if (readFileSync(join(DIR, name), "utf8") !== body) stale.push(`${name} (differs)`);
  }
  for (const name of present) if (!wanted.has(name)) stale.push(`${name} (no scenario renders it)`);
  if (stale.length) {
    console.error("config-generator fixtures are stale:\n  " + stale.join("\n  ") + "\nrun 'task docs:generator' and commit the result");
    process.exit(1);
  }
  console.log(`${wanted.size} config-generator fixtures match the generator`);
} else {
  rmSync(DIR, { recursive: true, force: true });
  mkdirSync(DIR, { recursive: true });
  for (const [name, body] of wanted) writeFileSync(join(DIR, name), body);
  console.log(`wrote ${wanted.size} config-generator fixtures to ${DIR}`);
}
